package com.vandorlabs.neoforge.screen;
import com.vandorlabs.neoforge.ModernFinishCatalog;
import net.minecraft.nbt.*;
/** Actual tile constructor/load/save scalar contract, independent of world callbacks. */
public final class ScreenSettingsChecks {
 private static NativeScreenSettings.Catalog catalog;
 public static final String[] KEYS={"VandorDataVersion","selectedScreen","redstoneEnabled","displayMode","framed","animationSpeedIndex","inputPanel","secondaryInputPanel","wallPosition","smallInput","housingTexture","RedstoneChannel","ChannelSignal","RedstoneChannels","RedstoneInverted","ChannelLevel","PrimarySurfaceTexture","SecondarySurfaceTexture","CeilingMounted","CeilingPosition","SurfaceTextureLayout","SurfaceTileSides"};
 public static final String[] FIELDS={"selectedScreen","redstoneEnabled","displayMode","framed","animationSpeedIndex","inputPanel","secondaryInputPanel","wallPosition","smallInput","housingTexture","RedstoneChannel","ChannelSignal","RedstoneChannels","RedstoneInverted","ChannelLevel","PrimarySurfaceTexture","SecondarySurfaceTexture","CeilingMounted","CeilingPosition","SurfaceTextureLayout","SurfaceTileSides"};
 public static void main(String[] args)throws Exception{java.util.List<String> inputs=new java.util.ArrayList<>();try(var reader=java.nio.file.Files.newBufferedReader(java.nio.file.Path.of(System.getProperty("screenInputs")))){for(var entry:com.google.gson.JsonParser.parseReader(reader).getAsJsonArray())inputs.add(entry.getAsJsonObject().get("id").getAsString());}catalog=new NativeScreenSettings.Catalog(){public String defaultInput(){return inputs.get(0);}public boolean validInput(String value){return inputs.contains(value);}public boolean validMaterial(int value){return ModernFinishCatalog.validChoice(value);}public int material(int value){return ModernFinishCatalog.storedChoice(value);}};java.security.MessageDigest hash=java.security.MessageDigest.getInstance("SHA-256");int cases=0;
  NativeScreenSettings fresh=NativeScreenSettings.fresh(catalog);digest(hash,fresh);cases++;
  for(String field:FIELDS)for(int kind=0;kind<10;kind++){CompoundTag input=input(field,kind);NativeScreenSettings tile=NativeScreenSettings.read(input,catalog);digest(hash,tile);cases++;}
  for(int mode=0;mode<3;mode++)for(int display=0;display<3;display++)for(int gate=0;gate<2;gate++)for(int signal=0;signal<2;signal++){CompoundTag input=new CompoundTag(),activation=new CompoundTag();activation.putInt("Mode",mode);activation.putIntArray("Textures",new int[]{-1,-1,-1,-1});activation.putIntArray("Playback",new int[]{-1,0,1,2});activation.putIntArray("Speeds",new int[]{-1,0,1,2});input.put("DisplayActivation",activation);input.putInt("displayMode",display);input.putBoolean("redstoneEnabled",gate!=0);input.putBoolean("ChannelSignal",signal!=0);NativeScreenSettings tile=NativeScreenSettings.read(input,catalog);digest(hash,tile);cases++;}
  CompoundTag opaque=new CompoundTag(),vehicle=new CompoundTag();vehicle.putString("FutureVehicle","opaque");opaque.put("VehicleMode",vehicle);opaque.putString("ScreenChipReader","unsupported");opaque.putString("DisplayActivation","future activation envelope");opaque.putInt("Foreign",33);CompoundTag before=opaque.copy();var saved=new NativeScreenSettings.Saved(opaque,catalog);opaque.putInt("Foreign",99);if(!saved.unchanged().equals(before)||!saved.edited(saved.settings).getCompound("VehicleMode").equals(vehicle)||!saved.edited(saved.settings).getString("ScreenChipReader").equals("unsupported")||!saved.edited(saved.settings).getString("DisplayActivation").equals("future activation envelope"))throw new AssertionError("Opaque screen state lost");StringBuilder out=new StringBuilder();for(byte b:hash.digest())out.append(String.format("%02x",b&255));if(!out.toString().equals("850c93cfa41b50bffb07a64b5af3abefcb617f26304a6a59eb28b1b717827e23"))throw new AssertionError("Screen scalar reference changed "+out);System.out.println("Native Screen scalar parity PASS cases="+cases+" sha256="+out);}
 public static CompoundTag input(String field,int kind){CompoundTag root=new CompoundTag();switch(kind){case 0:break;case 1:root.putInt(field,-9);break;case 2:root.putInt(field,0);break;case 3:root.putInt(field,1);break;case 4:root.putInt(field,Integer.MAX_VALUE);break;case 5:root.putBoolean(field,true);break;case 6:root.putString(field,"future_opaque_display");break;case 7:root.putString(field,"console_controls_biology_controls");break;case 8:root.putIntArray(field,new int[]{31,32});break;default:root.putIntArray(field,new int[]{-1});}return root;}
 private static void digest(java.security.MessageDigest hash,NativeScreenSettings tile)throws Exception{CompoundTag save=new CompoundTag();tile.write(save);StringBuilder text=new StringBuilder();for(String key:KEYS)text.append(key).append(':').append(save.contains(key)?save.get(key).toString():"absent").append(';');hash.update(text.toString().getBytes("UTF-8"));}
}
